from format_lecon import Lesson,paras,table,steps
from diagnostics import comparison
from medicaments import paracetamol
l=Lesson('Douleurs faciales, mandibulaires ou dentaires, trismus')
l.add('Ces symptômes désignent un territoire douloureux ou une limitation d’ouverture buccale, pas une maladie unique. Les {distinctions initiales} séparent origine dentaire, musculaire, articulaire, nerveuse, infectieuse et vasculaire. Une bouche bloquée ouverte évoque une autre situation qu’un trismus.',paras('Le trismus limite l’ouverture de la bouche ; il peut être réflexe, inflammatoire, mécanique ou lié à une atteinte profonde. Un trismus progressif sans cause claire exige également de rechercher une tumeur, une fibrose après irradiation ou une autre cause moins fréquente. Une luxation antérieure bloque plutôt la fermeture : le patient reste bouche ouverte.', 'Le siège ressenti ne désigne pas toujours l’organe malade. Une douleur des dents supérieures peut venir d’un sinus, une décharge faciale d’un nerf, et une fatigue douloureuse à la mastication d’une ischémie.'),(1,2,3,4,10,13))
l.add('Les {contextes cliniques} guident le raisonnement. Carie, éruption dentaire, mastication, traumatisme et infection respiratoire apportent des orientations différentes. Les dix diagnostics sont une sélection pédagogique sans rang chiffré de prévalence suisse.',paras('Les maladies dentaires et les troubles de l’appareil manducateur sont importants en première ligne. Une dent de sagesse partiellement sortie, un soin récent ou une mauvaise hygiène orientent l’examen sans prouver une infection bactérienne diffuse.', 'L’artérite à cellules géantes concerne habituellement les personnes de plus de 50 ans. Une névralgie survient souvent à un âge avancé, mais l’âge ne suffit pas à exclure une cause secondaire ; une douleur après traumatisme demande son propre bilan.'),(1,2,3,7,10,13,20))
an=l.subwindow('anatomie','Dents, mandibule et innervation',paras('La pulpe est un tissu vascularisé et innervé contenu dans la dent. Une inflammation pulpaire peut évoluer vers nécrose et infection périapicale ; une douleur qui diminue ne démontre donc pas la guérison.', 'La mandibule s’articule aux deux os temporaux. Muscles masticateurs, disque articulaire, dents et occlusion participent ensemble à son fonctionnement ; un impact peut provoquer plusieurs foyers de fracture.', 'Le nerf trijumeau véhicule une grande partie de la sensibilité faciale. Les artères alimentant les muscles masticateurs peuvent être atteintes dans l’artérite à cellules géantes, donnant une douleur d’effort différente d’une simple douleur articulaire.'),(1,2,3,10,13))
l.add('Les {bases anatomiques} expliquent les douleurs projetées et les complications. La proximité des espaces dentaires, du plancher buccal et du cou permet l’extension d’une infection. Une atteinte bilatérale de la mandibule peut aussi compromettre le soutien de la langue.',paras(an),(1,2,3,8,10,13))
l.add('Le {tri des urgences} vient avant la recherche de la dent responsable. Respiration, vision, état neurologique et traumatisme déterminent les premières actions. Un délai de consultation dentaire ordinaire ne convient pas aux signes de gravité.',table(['Priorité','🚩 Signes','Action'],[['E1 — Voies aériennes et infection.','Dyspnée, stridor, salive non déglutie, plancher gonflé, progression rapide, trismus important ou sepsis.','Évaluation hospitalière immédiate ; appel 144 en Suisse si menace vitale. Ne pas forcer l’ouverture ni retarder pour une radiographie dentaire.'],['E2 — Vision et vascularite.','Claudication de mâchoire, nouvelle céphalée, diplopie ou baisse visuelle après 50 ans.','Évaluation urgente ; signes visuels le jour même, traitement médical sans attendre la confirmation si suspicion forte.'],['E3 — Traumatisme.','Malocclusion, hématome sublingual, dent manquante, perte de connaissance ou douleur cervicale.','Évaluer les lésions associées et protéger les voies aériennes ; avis maxillo-facial.'],['E4 — Orbite et neurologie.','Œdème palpébral, exophtalmie, trouble oculomoteur, syndrome méningé ou déficit neurologique.','Hospitalisation urgente pour complication sinusienne ou autre urgence.'],['E5 — Douleur projetée cardiaque.','Douleur de mâchoire associée à oppression thoracique, dyspnée, sueurs, nausées ou malaise.','Évoquer une urgence coronarienne et appeler le 144 ; ne pas attendre le dentiste.'],['E6 — Contractures généralisées.','Trismus ou contractures faciales progressant vers spasmes du tronc, surtout après plaie et protection vaccinale incertaine.','Évoquer un tétanos et adresser immédiatement à l’hôpital.'],['Bilan accéléré.','Trismus progressif, ulcère persistant, masse cervicale, amaigrissement ou hypoesthésie inexpliquée.','Rechercher tumeur ou autre atteinte profonde, même sans fièvre.']]),(5,8,10,13,14,19,22,23))
l.add('L’anamnèse précise durée des crises, déclencheurs et évolution. Les {questions discriminantes} incluent signes dentaires, nasaux, pharyngés et généraux. Il faut relever les traitements, allergies, immunodépression et gestes déjà tentés.',table(['Question','Orientation'],[['Froid, chaud, sucre, douleur spontanée nocturne ?','Atteinte pulpaire ; caractériser la persistance après le stimulus.'],['Douleur à la morsure, tuméfaction, pus, dent de sagesse ?','Foyer apical, parodontal ou péricoronaire.'],['Bâillement, bouche bloquée ouverte, choc récent ?','Luxation ou fracture à distinguer.'],['Décharges déclenchées par effleurement ou brossage ?','Névralgie du trijumeau possible.'],['Nez bouché, écoulement, douleur jugale après rhume ?','Rhinosinusite ; chercher une origine dentaire si unilatérale.'],['Mal de gorge unilatéral, voix étouffée, salive difficile à avaler ?','Infection périamygdalienne ou profonde.'],['Fatigue douloureuse à mâcher, céphalée nouvelle, vision ?','Artérite à cellules géantes, surtout après 50 ans.']]),(1,3,4,5,7,10,12,13,20))
l.add('L’examen commence par les fonctions vitales et l’aspect général. L’{examen régional prudent} porte sur dents, muqueuses, plancher, pharynx, articulation, face et cou. On ne force pas une ouverture douloureuse pour obtenir un examen complet.',paras('Mesurer et décrire la limitation si possible ; distinguer ouverture réduite et fermeture impossible. Rechercher tuméfaction, asymétrie, pus, carie, capuchon gingival, plaie et modification de l’occlusion.', 'La palpation musculaire et articulaire doit rechercher la douleur habituelle du patient. Les tests pulpaires et les radiographies relèvent du bilan dentaire ; aucun test isolé ne remplace la concordance clinique.', 'Examiner sensibilité faciale et mentonnière, motricité, yeux, artères temporales et cou selon la présentation. Après traumatisme, une dent absente demande de préciser son devenir et de rechercher une inhalation si le contexte l’évoque.'),(1,2,3,5,7,10,13))
l.add('Le {tableau comparatif} organise les dix diagnostics retenus. L’ordre facilite l’apprentissage et ne mesure pas leur fréquence. Les urgences restent prioritaires quel que soit leur numéro.',comparison(),(1,2,3,4,5,7,8,10,12,13,20))
l.add('Le diagnostic repose sur un ensemble concordant. Les {critères et limites} évitent les raccourcis fondés sur un seul signe. Une amélioration sous antalgique ou antibiotique ne confirme pas à elle seule une hypothèse.',paras('Pulpite, abcès et péricoronarite ont des cibles anatomiques distinctes. Une douleur intense n’est pas une indication suffisante d’antibiotique ; une infection étendue peut au contraire nécessiter l’hôpital même si la douleur n’est pas maximale.', 'Une névralgie nécessite une description typique des crises et un bilan étiologique ; le simple contact entre un vaisseau et le nerf à l’IRM ne prouve pas le diagnostic. Un trouble temporo-mandibulaire doit reproduire la douleur habituelle et rester compatible avec l’absence d’alarme.', 'Claudication mandibulaire et trouble visuel justifient une suspicion vasculaire urgente. Un trismus peut accompagner abcès périamygdalien, infection dentaire ou autre affection ; il n’est pas spécifique d’un seul diagnostic.'),(5,7,8,9,12,13))
l.add('Les {examens complémentaires dirigés} répondent à une hypothèse. Une radiographie dentaire ne remplace pas le bilan d’une infection profonde ou d’un traumatisme complexe. La confirmation ne doit pas retarder les soins urgents.',table(['Contexte','Bilan'],[['Foyer dentaire.','Tests de sensibilité pulpaire, percussion, examen parodontal et imagerie dentaire ciblée.'],['Traumatisme mandibulaire.','Imagerie de la mandibule, panoramique ou TDM selon mécanisme et lésions associées ; avis chirurgical.'],['Névralgie du trijumeau.','Examen neurologique et IRM avec protocole adapté ; rechercher cause secondaire.'],['Infection profonde.','Biologie, prélèvements et imagerie selon spécialiste, après prise en compte des voies aériennes.'],['Artérite à cellules géantes.','Marqueurs inflammatoires, échographie vasculaire experte et/ou biopsie, avec traitement urgent si indiqué.'],['Rhinosinusite simple.','Diagnostic clinique ; imagerie si complication, atypie ou bilan spécialisé.']]),(1,4,5,7,10,12,13,14))
l.add('L’{algorithme clinique} relie urgence, localisation et traitement causal. Il prévoit un suivi et une solution en cas d’aggravation. La répétition de traitements empiriques ne remplace pas une nouvelle évaluation.',steps('Rechercher menace respiratoire, infection étendue, atteinte visuelle, complication orbitaire ou traumatisme grave ; penser aussi à une urgence coronarienne et au tétanos selon les signes associés.', 'Distinguer trismus et bouche bloquée ouverte ; examiner bouche, dents, pharynx, articulation, face et cou selon tolérance.', 'Caractériser douleur thermique, mécanique, électrique, nasosinusienne ou claudication d’effort.', 'Organiser le bilan dentaire ou spécialisé, avec les examens adaptés à l’hypothèse ; traiter sans attendre une confirmation qui retarderait une urgence.', 'Donner antalgie adaptée, traitement causal et consignes précises : retour immédiat si gonflement, difficulté respiratoire ou salivaire, fièvre avec aggravation ou signe visuel.'),(1,2,3,4,5,7,8,10,12,13,14,22,23))
l.add('La {prise en charge en Suisse} associe soulagement et traitement de la cause. Drainage, soins dentaires, réduction ou traitement neurologique répondent à des situations distinctes. Les antibiotiques ne traitent pas toutes les douleurs de la face.',paras(paracetamol(l))+paras('Pulpite isolée : traitement dentaire et antalgie, sans antibiotique systémique. Abcès : drainage et contrôle du foyer ; antibiotique lorsque l’extension, l’état général ou l’impossibilité de réaliser immédiatement les mesures locales le justifient.', 'Trouble temporo-mandibulaire : mesures conservatrices individualisées. Luxation et fracture : équipe formée, sans manipulation improvisée ; les sédatifs et anesthésiques demandent surveillance et prescription adaptée.', 'Névralgie : traitement spécifique, souvent carbamazépine selon bilan et notice suisse, détaillé dans sa monographie. Artérite fortement suspectée : corticothérapie urgente décidée médicalement ; ne pas attendre la biopsie. Les doses étrangères ne sont pas transposées en posologies AIPS.'),(1,2,7,8,9,10,12,13,15,16,17))
l.add('La {prévention et la surveillance} dépendent du mécanisme. L’hygiène dentaire, les soins précoces et la protection lors des activités à risque réduisent certaines causes. Une douleur récidivante ou persistante doit être réévaluée.',paras('Vérifier la vaccination et les soins des plaies pour prévenir le tétanos. Préserver l’hygiène buccale et traiter les lésions carieuses ; une fistule ou une amélioration spontanée ne dispense pas du soin causal. Après péricoronarite, discuter le devenir de la dent et le risque de récidive.', 'Pour l’appareil manducateur, éviter les contraintes excessives et suivre la physiothérapie si prescrite. Après luxation, limiter les grandes ouvertures selon l’équipe ; après fracture, respecter alimentation et suivi chirurgical.', 'Sous traitement de névralgie ou corticothérapie, planifier surveillance clinique et biologique. Signaler rash, fièvre, ulcérations, troubles visuels ou modification neurologique ; ne pas interrompre brutalement un traitement prolongé sans conseil médical.'),(1,2,8,10,11,12,13,16,17,23))
l.add('Une douleur dentaire ressentie peut avoir une origine extra-dentaire. Trismus et fermeture impossible doivent être distingués. Une infection profonde menace les voies aériennes ; une claudication avec signes visuels menace la vision. Le traitement causal et le suivi accompagnent toujours l’antalgie.',refs=(1,3,5,7,8,10,12,13))
l.quiz([('Un trismus est-il une bouche bloquée ouverte ?','Non : il limite l’ouverture ; une luxation antérieure bloque plutôt la fermeture.'),('La douleur la plus forte est-elle forcément bactérienne ?','Non : une pulpite peut être très douloureuse sans indication antibiotique.'),('Quels signes font craindre une infection profonde ?','Plancher gonflé, trismus important, difficulté à avaler la salive, dyspnée ou extension rapide.'),('Quel numéro suisse appeler si menace vitale ?','Le 144.'),('La présence de pus évacué prouve-t-elle la guérison ?','Non : le foyer dentaire doit être traité.'),('Une dent de sagesse partiellement sortie avec gencive inflammatoire évoque quoi ?','Une péricoronarite.'),('Que chercher après un choc avec malocclusion ?','Une fracture, d’autres lésions faciales et un traumatisme crânien ou cervical.'),('Peut-on réduire une mâchoire traumatisée sans bilan ?','Non : rechercher une fracture et recourir à une équipe formée.'),('Des décharges déclenchées par l’effleurement orientent vers quoi ?','Une névralgie du trijumeau, à confirmer et explorer.'),('Un contact vasculo-nerveux à l’IRM suffit-il ?','Non : il ne confirme pas à lui seul la névralgie.'),('Que suggère une douleur des dents supérieures avec obstruction nasale ?','Une sinusite, sans exclure une origine dentaire.'),('Une baisse visuelle avec claudication mandibulaire peut-elle attendre ?','Non : évaluation urgente et traitement médical si suspicion forte d’artérite.'),('Faut-il attendre la biopsie pour traiter une artérite fortement suspectée ?','Non.'),('Pourquoi vérifier tous les médicaments antalgiques pris ?','Pour éviter notamment le cumul et le surdosage en paracétamol.')],(1,3,4,5,7,8,10,12,13,15,20))
l.write()
